import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color, DirectionalLight, AmbientLight } from 'three/webgpu';
import { texture, float, uniform, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const visuals = config.intent?.visualSpec ?? {};

  const group = new Group();
  group.name = config.id ?? 'pricing-list-row';

  const CLEAN = [];
  const primitiveHandles = [];

  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  const ROW_W = 6.0;
  const ROW_H = 0.5;

  // --- Stage backdrop sliver (so the row never reads as void behind the displacement) ---
  const backGeo = new PlaneGeometry(ROW_W + 0.4, ROW_H + 0.4);
  const backMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.85,
    metalness: 0.45,
    emissive: surface,
    emissiveIntensity: 0.05,
  });
  const back = new Mesh(backGeo, backMat);
  back.position.set(0, 0, -0.05);
  group.add(back);
  CLEAN.push(() => { backGeo.dispose(); backMat.dispose(); });

  // --- Hero displaced textured plane (parallax-plane render mode) ---
  const dispPlaneGeo = new PlaneGeometry(ROW_W, ROW_H, 64, 64);
  const dispPlaneMat = new MeshStandardNodeMaterial({
    color: paper,
    roughness: 0.5,
    metalness: 0.5,
    envMapIntensity: 1.0,
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE?.SRGBColorSpace ?? null;
      dispPlaneMat.map = tex;
      dispPlaneMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      dispPlaneMat.displacementNode = texture(depthTex, uv()).r.mul(float(0.085));
      dispPlaneMat.needsUpdate = true;
    });
  }
  const dispPlane = new Mesh(dispPlaneGeo, dispPlaneMat);
  dispPlane.position.set(0, 0, 0.001);
  group.add(dispPlane);
  CLEAN.push(() => { dispPlaneGeo.dispose(); dispPlaneMat.dispose(); });

  // --- Subtle horizontal divider (the `divider` from spec) sits just below the row ---
  const divGeo = new PlaneGeometry(ROW_W * 0.94, 0.008);
  const divMat = new MeshStandardNodeMaterial({
    color: ink,
    roughness: 0.6,
    metalness: 0.4,
    emissive: ink,
    emissiveIntensity: 0.1,
  });
  const divider = new Mesh(divGeo, divMat);
  divider.position.set(0, -ROW_H / 2 - 0.018, 0.002);
  group.add(divider);
  CLEAN.push(() => { divGeo.dispose(); divMat.dispose(); });

  // --- Accent rim stripe (signal-red, <=10% of frame area) on the left edge ---
  const stripeGeo = new PlaneGeometry(0.04, ROW_H * 0.66);
  const stripeMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 0.85,
    roughness: 0.3,
    metalness: 0.4,
  });
  const stripe = new Mesh(stripeGeo, stripeMat);
  stripe.position.set(-ROW_W / 2 + 0.04, 0, 0.004);
  group.add(stripe);
  CLEAN.push(() => { stripeGeo.dispose(); stripeMat.dispose(); });

  // --- MSDF text content (rendered strictly from config items; no invented copy) ---
  const textMeshes = [];
  for (const item of items) {
    const content = (item && typeof item.text === 'string') ? item.text : '';
    if (!content) continue;
    const role = item.role ?? 'body';
    const sizeMap = { hero: 68, headline: 44, subhead: 30, body: 22, caption: 16 };
    const fontSize = item.typography?.fontSize ?? sizeMap[role] ?? 22;
    const colorHex = item.color ?? (role === 'headline' ? paper.getStyle() : '#b9bec9');
    const align = item.align ?? 'left';
    const txt = ctx.fontAtlas.createText(content, { fontSize, color: colorHex, align });
    if (item.position) txt.position.fromArray(item.position);
    else txt.position.set(-ROW_W / 2 + 0.25, 0, 0.01);
    group.add(txt);
    textMeshes.push(txt);
  }

  // --- Lighting node-locally (key + accent rim + ambient fill) ---
  // The scene already provides ambient ~0.6 + key ~1.2; add a node-local accent rim + cool fill key.
  const accentRim = new DirectionalLight(accent, 0.8);
  accentRim.position.set(-3.2, -0.4, 2.2);
  group.add(accentRim);

  const coolKey = new DirectionalLight('#fff5f6', 0.4);
  coolKey.position.set(3.0, 1.2, 3.0);
  group.add(coolKey);

  const ambFill = new AmbientLight('#0b0b10', 0.35);
  group.add(ambFill);
  CLEAN.push(() => {
    accentRim.dispose && accentRim.dispose();
    coolKey.dispose && coolKey.dispose();
    ambFill.dispose && ambFill.dispose();
  });

  // --- Primitive application: parallax-scroll (scroll) + depth-rotate (hover) ---
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const params = { ...(p.params ?? {}), trigger: p.trigger };
    try {
      const handle = ctx.primitives[p.name](group, params);
      if (handle) {
        primitiveHandles.push(handle);
        if (handle.timeline && typeof handle.timeline.play === 'function'
          && (p.trigger === 'load' || p.trigger === 'time' || p.trigger === 'scroll')) {
          handle.timeline.play();
        }
      }
    } catch (_) { /* primitive failure must not break node */ }
  }

  // --- Entrance timeline: rise-in (subtle) + weighted-settle, linear forbidden on hero motion ---
  const enterTl = gsap.timeline({ paused: true });
  gsap.set(group.position, { y: -0.15 });
  gsap.set(group.scale, { x: 0.96, y: 0.96, z: 0.96 });
  enterTl.to(group.position, { y: 0, duration: 0.6, ease: 'power3.out' }, 0);
  enterTl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.55, ease: 'power2.out' }, 0);
  enterTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.55);

  // --- Hover Interaction (preset:rise-in subtle 0.15 scene units) ---
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.pause();

  let hovering = false;
  const hoverOn = () => {
    hovering = true;
    gsap.to(group.position, { y: 0.15, duration: 0.45, ease: 'power3.out', overwrite: true });
  };
  const hoverOff = () => {
    hovering = false;
    gsap.to(group.position, { y: 0, duration: 0.4, ease: 'power3.out', overwrite: true });
  };

  // --- Click Interaction: emit hub-pricing.select + press-down 120ms ---
  const click = () => {
    ctx.emit('hub-pricing.select', { id: config.id ?? 'pricing-row', payload: config.binding ?? null });
    const ptl = gsap.timeline();
    ptl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' })
       .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' });
  };

  group.userData.handlers = {
    'pointerenter': hoverOn,
    'pointerleave': hoverOff,
    'pointerdown': click,
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    enterTl.kill();
    hoverTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    primitiveHandles.forEach((h) => { try { h.cleanup && h.cleanup(); } catch (_) {} });
    textMeshes.forEach((m) => { try { m.geometry?.dispose?.(); m.material?.dispose?.(); } catch (_) {} });
    CLEAN.forEach((fn) => { try { fn(); } catch (_) {} });
  };

  enterTl.play();
  return group;
}
